venues = [
    {
        "id": p["id"],
        "gender": p["type"],
        "capacity": p["capacity"],
        "lat": p["lat"],
        "lng": p["lng"],
        "distance_to_event_km": round(p["event_distance"] / 1000, 3),
    }
    for p in places
]

delegations = [
    {
        "id": g["id"],
        "home_city": g["origin_city"],
        "men": g["men"],
        "women": g["women"],
        "home_distance": g["origin_city_distance"],
    }
    for g in groups
]

placements = [
    {"delegation_id": group_id, "gender": gender, "venue_id": place_id}
    for gender, place_id, group_id in assignment
]

with open("viz_data.json", "w") as f:
    json.dump({
        "venues": venues,
        "delegations": delegations,
        "placements": placements,
        "city_conflicts": city_conflicts,
    }, f)

print(f"Wrote viz_data.json ({len(venues)} venues, {len(delegations)} delegations, {len(placements)} placements)")
